/// <summary>
/// designed from AVA
/// </summary>
internal final class AVADocuRestrictionRefInit
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args        _args)
{
    AVADocuRestrictionReference         restrictionRef;
    AVADocuRestrictionReference         notExistRef;
    DocuRef                             docuRef;
    RecordInsertList                    recInsList = new RecordInsertList(tableNum(AVADocuRestrictionReference));
    AVADocuRestriction                  docuRestriction;

    select firstonly    docuRestriction
        order by Num;

    while select docuRef
        notexists join notExistRef
        where notExistRef.DocuRefRecId == docuRef.RecId
    {
        restrictionRef.DocuRefRecId = docuRef.RecId;
        restrictionRef.DocuRestrictionNum = docuRestriction.Num;
        recInsList.add(restrictionRef);
    }

    recInsList.insertDatabase();
}
